    H,W=np.array(I).shape; seen=np.zeros((H,W),bool); cs=[]
    for r in range(H):
        for c in range(W):
            if int(I[r,c])!=bg and not seen[r,c]:
                col=int(I[r,c]); st=[(r,c)]; seen[r,c]=True; cells=set()
